const cbData = String(update.callback_query?.data || '').trim();
const cbId = update.callback_query?.id;

const _ctx = this;
let lastTgResult = null;
async function tgPost(endpoint, body) {
  try {
    if (_ctx && _ctx.helpers && typeof _ctx.helpers.httpRequest === 'function') {
      const res = await _ctx.helpers.httpRequest({
        method: 'POST',
        url: `https://api.telegram.org/bot${TG_TOKEN}/${endpoint}`,
        headers: { 'Content-Type': 'application/json' },
        body: body,
        json: true
      });
      lastTgResult = res;
      return res;
    }
  } catch (e) {
    lastTgResult = { ok: false, error: String(e.message || e) };
    return lastTgResult;
  }
}

async function sendOrEdit(textStr, inlineKeyboard, forceNew = false) {
  if (messageId && !forceNew) {
    const res = await tgPost('editMessageText', {
      chat_id: ADMIN_CHAT_ID,
      message_id: messageId,
      text: textStr,
      parse_mode: 'Markdown',
      disable_web_page_preview: true,
      reply_markup: { inline_keyboard: inlineKeyboard }
    });
    if (res && res.ok) return res;
  }
  return await tgPost('sendMessage', {
    chat_id: ADMIN_CHAT_ID,
    text: textStr,
    parse_mode: 'Markdown',
    disable_web_page_preview: true,
    reply_markup: { inline_keyboard: inlineKeyboard }
  });
}

if (cbId) {
  await tgPost('answerCallbackQuery', { callback_query_id: cbId });
