function getClickableJdUrl(row) {
  const pageLink = String(row?.['Applied Page link'] || '').trim();
  if (pageLink) return pageLink;
  const jd = String(row?.['Position - Description'] || '');
  const m = jd.match(/https?:\/\/[^\s)]+/i);
  if (m) return m[0];
  const site = String(row?.['Company website'] || '').trim();
  return site || SHEET_URL;
}

// Helper to render the Paginated 23-Portal Vault List
async function renderPortalList(filterMode, pageIdx) {
  const list = filterMode === 'pending'
    ? pendingPortals
    : (filterMode === 'auth' ? authPortals : vaultRows);
  const pageSize = 8;
  const totalPages = Math.max(1, Math.ceil(list.length / pageSize));
  const safePage = Math.max(0, Math.min(pageIdx, totalPages - 1));
  const slice = list.slice(safePage * pageSize, (safePage + 1) * pageSize);

  const filterLabel = filterMode === 'pending'
    ? `🟡 Pending Authentication (${pendingPortals.length})`
    : (filterMode === 'auth' ? `🟢 Logged In / Authenticated (${authPortals.length})` : `📋 All Portals (${vaultRows.length})`);

  const siteLines = slice.map((v, i) => {
    const globalIdx = vaultRows.findIndex(x => x.site_name === v.site_name);
    const isAuth = String(v.auth_status || '').toLowerCase().startsWith('authenticated');
    const icon = isAuth ? '🟢' : '🟡';
    const hasProfile = Boolean(v.session_cookies);
    const profTag = isAuth ? (hasProfile ? ' _(Profile & Prefs Synced)_' : ' _(Tap to Complete Profile)_') : ' _(Needs Login)_';
    const urlPart = v.portal_url ? `[Open Site](${v.portal_url})` : '';
    return `${icon} *#${globalIdx + 1} ${v.site_name}*${profTag} ${urlPart}`;
  }).join('\n');

  const kb = [
    [
      { text: `${filterMode === 'pending' ? '🔘' : '⚪'} Pending (${pendingPortals.length})`, callback_data: 'cred_list:pending:0' },
      { text: `${filterMode === 'auth' ? '🔘' : '⚪'} Auth (${authPortals.length})`, callback_data: 'cred_list:auth:0' },
      { text: `${filterMode === 'all' ? '🔘' : '⚪'} All (${vaultRows.length})`, callback_data: 'cred_list:all:0' }
    ]
  ];

  for (const v of slice) {
    const globalIdx = vaultRows.findIndex(x => x.site_name === v.site_name);
    const isAuth = String(v.auth_status || '').toLowerCase().startsWith('authenticated');
    const icon = isAuth ? '🟢' : '🟡';
    const statusShort = isAuth ? 'Auth + Profile' : 'Pending Auth';
    kb.push([{ text: `${icon} #${globalIdx + 1} ${v.site_name} (${statusShort})`, callback_data: `cred_idx:${globalIdx}` }]);
  }

  if (totalPages > 1) {
    const navRow = [];
    if (safePage > 0) navRow.push({ text: `⬅️ Page ${safePage}`, callback_data: `cred_list:${filterMode}:${safePage - 1}` });
    if (safePage < totalPages - 1) navRow.push({ text: `Page ${safePage + 2} ➡️`, callback_data: `cred_list:${filterMode}:${safePage + 1}` });
    kb.push(navRow);
  }

  kb.push([{ text: '🛠️ Complete All Logged-In Profiles & Prefs', callback_data: 'cmd:complete_all_profiles' }]);
  kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

  await sendOrEdit(
    `🔐 *Portal Authentication & Profile Manager*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `*Filter:* ${filterLabel} — *Page ${safePage + 1}/${totalPages}*\n\n` +
    `${siteLines || '• None in this filter'}\n\n` +
    `💡 *Logged in without saving credentials or preferences?*\n` +
    `_Tap any portal below and select_ *✅ Just Logged In -> Complete Profile & Prefs* _to auto-populate your Master Resume PDF, 29 Skills, 3 Coursera Certs, and EU/Australia/Global Remote preferences!_`,
    kb
  );
}

// Helper to render Learned Rules Manager (Unlearn / Delete)
async function renderRulesManager(customBanner = '') {
  const resRules = allLearnedRules.filter(r => !String(r.section_name || '').toLowerCase().includes('cover') && String(r.section_name || '').toLowerCase() !== 'cl');
  const clRules = allLearnedRules.filter(r => String(r.section_name || '').toLowerCase().includes('cover') || String(r.section_name || '').toLowerCase() === 'cl');

  const resList = resRules.map(r => `• *#${r.id}* \`[${r.section_name}]\` _(${r.role_category})_: ${String(r.rule_instruction).slice(0, 110)}...`).join('\n') || '• _No active Resume learned rules_';
  const clList = clRules.map(r => `• *#${r.id}* \`[${r.section_name}]\`: ${String(r.rule_instruction).slice(0, 110)}...`).join('\n') || '• _No active Cover Letter learned rules_';

  const kb = [];
  for (const r of allLearnedRules.slice(0, 10)) {
    const isCl = String(r.section_name || '').toLowerCase().includes('cover') || String(r.section_name || '').toLowerCase() === 'cl';
    const typeLabel = isCl ? 'CL' : `Resume:${r.section_name}`;
    kb.push([{ text: `🗑️ Unlearn Rule #${r.id} (${typeLabel})`, callback_data: `unlearn_id:${r.id}` }]);
  }
  kb.push([{ text: `🗑️ Delete ALL Resume Rules (${resRules.length})`, callback_data: 'unlearn_bulk:resume' }]);
  kb.push([{ text: `🗑️ Delete ALL Cover Letter Rules (${clRules.length})`, callback_data: 'unlearn_bulk:cl' }]);
  kb.push([{ text: '⚠️ Delete ALL Rules Totally (Wipe All)', callback_data: 'unlearn_bulk:all' }]);
  kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

  await sendOrEdit(
    (customBanner ? `${customBanner}\n━━━━━━━━━━━━━━━━━━━━━━━━\n` : '') +
    `🧠 *Learned Rules Manager (Unlearn / Delete)*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📄 *Resume Rules (${resRules.length} Active):*\n${resList}\n\n` +
    `✉️ *Cover Letter Rules (${clRules.length} Active):*\n${clList}\n\n` +
    `_Tap any rule button below to unlearn it immediately, or wipe all Resume / Cover Letter rules totally:_`,
    kb
  );
}

// Helper to build Referral & HR Follow-Up Items across Job Application Sheet + Reference Sheet
function getReferralFollowUpItems() {
  const refMap = {};
  for (const rc of refContacts) {
    refMap[String(rc.company_name || '').trim().toLowerCase()] = rc;
  }

  const items = [];
  for (const r of jobRows) {
    const sNo = String(r['S. No.'] || '').trim();
    if (!sNo) continue;
    const comp = String(r['Company'] || '').trim();
    if (!comp) continue;
    const title = String(r['Position - Title'] || 'Target Role').trim();
    const refCol = String(r['Reference'] || '').trim();
    const hrCol = String(r['HR'] || '').trim();
    const hrEmailCol = String(r['HR Email'] || '').trim();
    const statusCol = String(r['Status'] || '').trim();
    const followUpDate = String(r['Follow up Date'] || '').trim();
    const matchedRef = refMap[comp.toLowerCase()] || {};

    const isReferral = Boolean(refCol) || statusCol.toLowerCase().includes('referral') || Boolean(matchedRef.referrer_name);
    const hasNamedHr = Boolean(hrCol && !hrCol.toLowerCase().includes('talent acquisition') && !hrCol.toLowerCase().includes('risk analytics')) || Boolean(hrEmailCol);

    if (isReferral || hasNamedHr) {
      const contactName = refCol || hrCol || matchedRef.referrer_name || 'Hiring Team';
      const contactEmail = hrEmailCol || matchedRef.referrer_email || '';
      const contactSocial = matchedRef.referrer_social || '';
      items.push({
        type: 'job',
        sNo,
        company: comp,
        title,
        contactName,
        contactEmail,
        contactSocial,
        isReferral,
        followUpDate: followUpDate || todayMDY,
        notes: String(r['Notes'] || '')
      });
    }
  }

  // Also include Reference Sheet rows that have an email or active note (like Axtria -> Ashish Chandra)
  for (const rc of refContacts) {
    const alreadyInJobs = items.some(x => x.company.toLowerCase() === String(rc.company_name || '').toLowerCase());
    if (!alreadyInJobs && (rc.referrer_email || rc.referrer_name)) {
      items.push({
        type: 'refsheet',
        sNo: `REF-${rc.company_name}`,
        company: rc.company_name,
        title: 'Senior Data Analyst / Analytics Role',
        contactName: rc.referrer_name,
        contactEmail: rc.referrer_email || '',
        contactSocial: rc.referrer_social || '',
        isReferral: true,
        followUpDate: todayMDY,
        notes: rc.notes || ''
      });
    }
  }
  return items;
}

let rawAction = cbData || text || '/menu';
if (rawAction === 'menu_pending') rawAction = 'cred_list:pending:0';
else if (rawAction === 'cmd:edit_creds' || rawAction === '/edit_creds' || rawAction === '/vault' || rawAction === '/portals') rawAction = 'cred_list:all:0';
else if (rawAction === 'cmd:mail_drafts' || rawAction === '/mail_drafts' || rawAction === '/referrals') rawAction = 'cmd:ref_followups';
else if (rawAction === '/rules' || rawAction.toLowerCase() === 'unlearn') rawAction = 'cmd:rules';

const strippedAlpha = text.replace(/\s+/g, '');
const is16CharAppPw = !cbData && !text.startsWith('/') && /^[a-zA-Z]{16}$/.test(strippedAlpha) && (text.trim().split(/\s+/).length === 4 || botState.pending_action === 'SET_GMAIL_APP_PASSWORD');
if (is16CharAppPw) {
  botState.pending_action = 'SET_GMAIL_APP_PASSWORD';
}
const action = rawAction;

// ============================================================================
// 1. Handle Text Replies for Rework / Credentials / Referrer Email / Gmail App Password
// ============================================================================
if (!cbData && text && !text.startsWith('/') && botState.pending_action) {
  const pAct = botState.pending_action;
  const targetId = botState.target_id;
  const scope = botState.scope || 'ONE_OFF';

  if (pAct === 'REWORK_RESUME') {
    const noteText = scope === 'ONE_OFF' ? `[For this resume only] ${text}` : text;
    sheetUpdates.push({
      'S. No.': String(targetId),
      'Notes by Reviewer': noteText,
      'Resume Status': 'Needs Rework'
    });
    if (scope === 'LEARN') {
      sqlQueries.push(`INSERT INTO learned_rules (section_name, role_category, rule_instruction, triggered_by_comment, is_active) VALUES ('global', 'ALL', '${esc(text)}', '${esc(text)}', TRUE);`);
    }
    sqlQueries.push(`DELETE FROM job_hunter_bot_state WHERE chat_id = '${ADMIN_CHAT_ID}';`);
    await sendOrEdit(
      `🛠️ *Resume Rework Queued (#${targetId})*\n` +
      `📝 *Note:* "${text}"\n` +
      `🎯 *Scope:* *${scope === 'ONE_OFF' ? '📌 This Job Only' : '🧠 Saved to Lessons Learnt'}*\n\n` +
      `_Workflow 2 is now rewriting the section & rendering the updated PDF._`,
      collapsedMenuKeyboard,
      true
    );
  } else if (pAct === 'REWORK_CL') {
    const noteText = scope === 'ONE_OFF' ? `[For this cover letter only] ${text}` : text;
    sheetUpdates.push({
      'S. No.': String(targetId),
      'Notes for CL': noteText,
      'Cover Letter Status': 'Needs Rework'
    });
    if (scope === 'LEARN') {
      sqlQueries.push(`INSERT INTO learned_rules (section_name, role_category, rule_instruction, triggered_by_comment, is_active) VALUES ('cover_letter', 'ALL', '${esc(text)}', '${esc(text)}', TRUE);`);
    }
    sqlQueries.push(`DELETE FROM job_hunter_bot_state WHERE chat_id = '${ADMIN_CHAT_ID}';`);
    await sendOrEdit(
      `🛠️ *Cover Letter Rework Queued (#${targetId})*\n` +
      `📝 *Note:* "${text}"\n` +
      `🎯 *Scope:* *${scope === 'ONE_OFF' ? '📌 This CL Only' : '🧠 Saved to Lessons Learnt'}*`,
      collapsedMenuKeyboard,
      true
    );
  } else if (pAct === 'SET_PORTAL_CREDS') {
    const parts = text.split('|').map(s => s.trim());
    const userVal = esc(parts[0] || 'user@example.com');
    const passVal = esc(parts[1] || '');
    const safeSite = esc(targetId);
    sqlQueries.push(`
      INSERT INTO portal_credentials_vault (site_name, login_method, auth_email, communication_email, username, encrypted_password, auth_status, updated_at)
      VALUES ('${safeSite}', 'Username & Password', '${userVal}', 'user@example.com', '${userVal}', '${passVal}', 'Authenticated', NOW())
      ON CONFLICT (site_name) DO UPDATE SET
        login_method = 'Username & Password',
        auth_email = '${userVal}',
        communication_email = 'user@example.com',
        username = '${userVal}',
        encrypted_password = '${passVal}',
        auth_status = 'Authenticated',
        updated_at = NOW();
      DELETE FROM job_hunter_bot_state WHERE chat_id = '${ADMIN_CHAT_ID}';
    `);
    trackerUpdates.push({
      'Site': targetId,
      'Updated Resume': `Synced - Sumanto_Banerjee-Master_Resume.pdf (${todayIso})`,
      'Skills Updated': `Synced (29 Skills + 3 Certs + EU/AU/Global Prefs - ${todayIso})`,
      'Region / Remote Focus': 'EU, Australia, Global Remote, UAE & India',
      'Authentication Status': `Authenticated (Credentials + Profile Synced ${todayIso})`
    });
    triggerSyncProfile = true;
    if (userMsgId) {
      deleteMessageAfter5Min = { chat_id: ADMIN_CHAT_ID, message_id: userMsgId, label: `${targetId} credentials` };
      sqlQueries.push(`INSERT INTO telegram_ephemeral_messages (message_id, chat_id, delete_at, deleted) VALUES (${Number(userMsgId)}, '${ADMIN_CHAT_ID}', NOW() + INTERVAL '5 minutes', FALSE) ON CONFLICT (message_id) DO NOTHING;`);
    }
    const credsKb = userMsgId
      ? [[{ text: '🗑️ Delete Password Message Now', callback_data: `del_msg:${userMsgId}` }], ...collapsedMenuKeyboard]
      : collapsedMenuKeyboard;
    await sendOrEdit(
      `✅ *Saved Credentials & Auto-Completing Profile for ${targetId}*\n` +
      `• *Login:* \`${userVal}\`\n` +
      `• *Comm Email:* \`user@example.com\`\n` +
