    `3️⃣ *Day 2+ Poised Slide-In (Already Applied / Future Roles):*\n` +
    `\`Thanks for connecting${insider ? ', ' + insider : ''}. I recently applied for the ${role} role at ${comp} and wanted to share my profile in case my background in data modelling and BI is a fit for this or upcoming openings. Either way, glad to be connected.\`\n\n` +
    `🔗 [Find ${comp} Analytics Insiders on LinkedIn](${searchUrl})`,
    [
      [{ text: '💬 Paste a Post -> Get Sentiment-Matched Reply', callback_data: 'cmd:post_reply' }],
      [{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]
    ]
  );
}

else if (action.startsWith('/network') || action === 'cmd:network') {
  await sendOrEdit(
    `🤝 *Loading Poised LinkedIn Playbook & Sentiment Guide...*\n` +
    `_Workflow 7 is preparing your concise, sentiment-matched engagement notes now._`,
    backToMenuRow
  );
}
else if (action.startsWith('/drafts') || action === 'cmd:drafts') {
  const reviewRows = jobRows.filter(r =>
    ['Ready for Review', 'Create one', 'Needs Rework'].includes(String(r['Resume Status'] || '').trim()) ||
    ['Ready for Review', 'Create one', 'Needs Rework'].includes(String(r['Cover Letter Status'] || '').trim())
  );

  if (reviewRows.length === 0) {
    await sendOrEdit(
      `✅ *All Resumes & Cover Letters Reviewed!*\nNo pending drafts waiting for approval.\n\n🔗 [Open Job Application Sheet](${SHEET_URL})`,
      backToMenuRow
    );
  } else {
    for (const r of reviewRows.slice(0, 4)) {
      const sNo = r['S. No.'];
      const comp = r['Company'] || 'Target Company';
      const title = r['Position - Title'] || 'Role';
      const resSt = r['Resume Status'] || 'N/A';
      const clSt = r['Cover Letter Status'] || 'Staged';
      const resUrl = r['Resume'] || SHEET_URL;
      const clUrl = r['Cover Letter'] || '';
      const jdUrl = getClickableJdUrl(r);

      const kb = [
        [{ text: `✅ Approve #${sNo} (No Learn)`, callback_data: `apr_nolearn_res:${sNo}` }],
        [{ text: `🧠 Approve & Learn #${sNo}`, callback_data: `apr_res:${sNo}` }],
        [{ text: `📝 Approve + Create CL #${sNo}`, callback_data: `apr_res_cl:${sNo}` }],
        [{ text: `📌 Rework #${sNo} (This Job)`, callback_data: `rwk_res_1:${sNo}` }],
        [{ text: `🧠 Rework #${sNo} (Learn Rule)`, callback_data: `rwk_res_l:${sNo}` }]
      ];
      if (clUrl || clSt === 'Ready for Review') {
        kb.push([{ text: `✅ Approve CL #${sNo}`, callback_data: `apr_cl:${sNo}` }]);
        kb.push([{ text: `📌 Rework CL (This Job)`, callback_data: `rwk_cl_1:${sNo}` }]);
      }
      kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

      await tgPost('sendMessage', {
        chat_id: ADMIN_CHAT_ID,
        parse_mode: 'Markdown',
        disable_web_page_preview: true,
        text:
          `📝 *Review Row #${sNo}: ${comp}*\n` +
          `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
          `💼 *Role:* ${title}\n` +
          `📄 *Resume:* \`${resSt}\` | ✉️ *CL:* \`${clSt}\`\n\n` +
          `🔗 [View Job Description (JD)](${jdUrl})\n` +
          `📥 [Open Resume PDF](${resUrl})` +
          (clUrl ? `\n📥 [Open Cover Letter PDF](${clUrl})` : ''),
        reply_markup: { inline_keyboard: kb }
      });
    }
  }
}
else if (action.startsWith('/eod') || action === 'cmd:eod') {
  const inPortal = eodLogs.filter(e => e.apply_channel === 'IN_PORTAL');
  const external = eodLogs.filter(e => e.apply_channel !== 'IN_PORTAL');
  await sendOrEdit(
    `🌙 *End-of-Day (EOD) Apply Summary*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `⚡ *Inside Portals (Easy Apply):* *${inPortal.length}*\n` +
    (inPortal.map(j => `• *#${j.s_no} ${j.company_name}* — ${j.position_title}`).join('\n') || '• None') +
    `\n\n🌐 *Outside Portals (Career Sites):* *${external.length}*\n` +
    (external.map(j => `• *#${j.s_no} ${j.company_name}* — ${j.position_title}`).join('\n') || '• None') +
    `\n\n📧 *Comm Email:* \`user@example.com\`\n` +
    `🔗 [Open Job Application Sheet](${SHEET_URL})`,
    backToMenuRow
  );
}
else if (action.startsWith('/enrich') || action === 'cmd:enrich') {
  let enriched = 0;
  for (const r of jobRows) {
    const sNo = String(r['S. No.'] || '').trim();
    if (!sNo) continue;
    const title = String(r['Position - Title'] || '').trim();
    const jd = String(r['Position - Description'] || '').trim();
    const comp = String(r['Company'] || '').trim();
    const status = String(r['Status'] || '').trim();
    if (!title && !jd && !comp && !status) continue;

    const patch = { 'S. No.': sNo };
    let changed = false;
    if (!String(r['Resume_id'] || '').trim()) { patch['Resume_id'] = `RES-${sNo}`; changed = true; }
    if (!String(r['Industry'] || '').trim()) { patch['Industry'] = 'Technology & Data Analytics'; changed = true; }
    if (!String(r['Location'] || '').trim()) { patch['Location'] = 'India (Hybrid / Remote)'; changed = true; }
    const appOn = String(r['Applied On'] || '').trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(appOn)) {
      const [y, m, d] = appOn.split('-').map(Number);
      patch['Applied On'] = `${m}/${d}/${y}`;
      changed = true;
    }
    const folUp = String(r['Follow up Date'] || '').trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(folUp)) {
      const [y, m, d] = folUp.split('-').map(Number);
      patch['Follow up Date'] = `${m}/${d}/${y}`;
      changed = true;
    }
    if (changed) {
      sheetUpdates.push(patch);
      enriched++;
    }
  }
  await sendOrEdit(
    `✨ *Non-Destructive Enrichment Done*\n` +
    `• *Rows Enriched/Normalized:* *${enriched}*`,
    backToMenuRow
  );
}
else if (action.startsWith('apr_res:') || action.startsWith('apr_res_cl:')) {
  const withCl = action.startsWith('apr_res_cl:');
  const sNo = action.split(':')[1];
  const row = findRowBySNo(sNo);
  const jdText = String(row?.['Position - Description'] || '');
  const autoNeedsCl = withCl || /cover\s*letter/i.test(jdText) || String(row?.['Notes for CL'] || '').includes('MODAL_CL_REQUIRED');

  const patch = { 'S. No.': String(sNo), 'Resume Status': 'LGTM' };
  if (autoNeedsCl) patch['Cover Letter Status'] = 'Create one';
  sheetUpdates.push(patch);

  await sendOrEdit(
    `✅ *Approved & Learned Resume #${sNo} (${row?.['Company'] || 'Target'})*\n` +
    (autoNeedsCl ? `• *Stage 2 Triggered:* Creating Cover Letter via WF 3!` : `• *Cover Letter:* Not required.`),
    backToMenuRow
  );
}
else if (action.startsWith('apr_cl:')) {
  const sNo = action.split(':')[1];
  sheetUpdates.push({ 'S. No.': String(sNo), 'Cover Letter Status': 'LGTM' });
  await sendOrEdit(`✅ *Approved Cover Letter #${sNo}!*`, backToMenuRow);
}
else if (action.startsWith('rwk_res_1:') || action.startsWith('rwk_res_l:') || action.startsWith('rwk_cl_1:') || action.startsWith('rwk_cl_l:')) {
  const parts = action.split(':');
  const prefix = parts[0];
  const sNo = parts[1];
  const isRes = prefix.startsWith('rwk_res');
  const scope = prefix.endsWith('_1') ? 'ONE_OFF' : 'LEARN';
  const pAct = isRes ? 'REWORK_RESUME' : 'REWORK_CL';
  const row = findRowBySNo(sNo);

  sqlQueries.push(`
    INSERT INTO job_hunter_bot_state (chat_id, pending_action, target_id, scope, updated_at)
    VALUES ('${ADMIN_CHAT_ID}', '${pAct}', '${sNo}', '${scope}', NOW())
    ON CONFLICT (chat_id) DO UPDATE SET pending_action = '${pAct}', target_id = '${sNo}', scope = '${scope}', updated_at = NOW();
  `);

  await sendOrEdit(
    `✏️ *Rework ${isRes ? 'Resume' : 'CL'} #${sNo} (${row?.['Company'] || 'Target'})*\n` +
    `🎯 *Scope:* *${scope === 'ONE_OFF' ? '📌 This Job Only' : '🧠 Save to Lessons Learnt'}*\n` +
    `🔗 [View JD](${getClickableJdUrl(row)})\n\n` +
    `_Reply with your feedback note:_`,
    backToMenuRow
  );
}
else if (action.startsWith('/sync_profile') || action === 'cmd:sync_profile') {
  triggerSyncProfile = true;
  await sendOrEdit(
    `🔄 *Triggering Workflow 6 (Master Resume, 29 Skills, 3 Coursera Certs & All Logged-In Portal Profiles Sync)...*`,
    backToMenuRow
  );
}
else {
  await sendOrEdit(getHeaderSummary(), collapsedMenuKeyboard, false);
}

let targetWorkflowId = '';
if (action === 'cmd:run_hunter' || action === '/run') {
  targetWorkflowId = 'kYpYvF2pM66RYXCC';
} else if (triggerSyncProfile || action.startsWith('/sync_profile') || action === 'cmd:sync_profile') {
  targetWorkflowId = 'QL9218oxuBxpYefQ';
} else if (action.startsWith('/network') || action === 'cmd:network') {
  targetWorkflowId = 'DK7BGr5CVZrkPe6W';
} else if (action.startsWith('apr_res:')) {
  targetWorkflowId = 'lXNGL9OcyVVtCBuz';
} else if (action.startsWith('apr_res_cl:') || action.startsWith('apr_cl:')) {
  targetWorkflowId = 'T4k9rXZ2CKK72xZS';
} else if (!cbData && text && !text.startsWith('/') && botState.pending_action === 'REWORK_RESUME') {
  targetWorkflowId = 'lXNGL9OcyVVtCBuz';
} else if (!cbData && text && !text.startsWith('/') && botState.pending_action === 'REWORK_CL') {
  targetWorkflowId = 'T4k9rXZ2CKK72xZS';
}

return [{
  json: {
    ok: true,
    action,
    lastTgResult,
    targetWorkflowId,
    shouldExecuteSubworkflow: Boolean(targetWorkflowId),
    sheetUpdates,
    trackerUpdates,
    emailPayload,
    deleteMessageAfter5Min,
    combinedSql: sqlQueries.length > 0 ? sqlQueries.join('\n') : 'SELECT 1;'
  }
}];

const p = $input.first()?.json?.emailPayload;
if (!p || !p.toEmail) return [];
return [{ json: p }];

const d = $input.first()?.json?.deleteMessageAfter5Min;
if (!d || !d.message_id) return [];
return [{ json: d }];

const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const chatId = $input.first()?.json?.chat_id || '8873019272';
const msgId = Number($input.first()?.json?.message_id || 0);
let delRes = null;
if (msgId) {
  try {
    delRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TG_TOKEN}/deleteMessage`,
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: chatId, message_id: msgId },
      json: true
    });
  } catch (e) {
    delRes = { ok: false, error: String(e.message || e) };
  }
}
return [{ json: { deleted: true, message_id: msgId, delRes } }];
